pre.code:
:root {
  color-scheme: light;
  --bg: #FFFFFF;
  --surface: #F7F8F9;
  --text: #16181B;
  --muted: #5B6169;
  --border: rgba(15, 23, 32, 0.1);

  --hero-accent: #C2660A;
  --about-accent: #16824A;
  --contact-accent: #1668A0;
  --projects-accent: #B23856;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-height: 100vh;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: var(--bg);
  color: var(--text);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.page-content {
  width: min(1100px, calc(100% - 2rem));
  margin: 0 auto;
  display: grid;
  gap: 6.5rem;
  padding: 3rem 0 5rem;
}

.section,
.tech-section {
  position: relative;
  overflow: hidden;
  padding: 1.5rem 0;
}

.hero {
  min-height: 68vh;
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 0;
}

.hero .section-inner {
  position: relative;
  z-index: 1;
  text-align: center;
  pointer-events: none;
}

.hero h1 {
  font-size: clamp(2rem, 5vw, 3rem);
  line-height: 1.1;
  margin: 0;
}

.code-call {
  color: var(--hero-accent);
  font-family: "Fira Code", "Courier New", Courier, monospace;
}

.subtitle {
  margin: 1rem auto 0;
  max-width: 46rem;
  font-size: clamp(1.1rem, 1.4vw, 1.4rem);
  color: var(--muted);
}

.section-tag {
  display: inline-flex;
  font-family: "Fira Code", "Courier New", Courier, monospace;
  color: var(--hero-accent);
  font-size: 1.05rem;
  letter-spacing: 0.08em;
  text-transform: lowercase;
  margin-bottom: 1.25rem;
}

.about .section-tag {
  color: var(--about-accent);
}

.projects .section-tag {
  color: var(--projects-accent);
}

.contact .section-tag {
  color: var(--contact-accent);
}

.section-tag-close {
  display: inline-flex;
  margin-top: 2rem;
}

.section-inner {
  max-width: 900px;
}

.about .section-inner,
.projects .section-inner,
.contact .section-inner {
  padding-left: clamp(1rem, 5vw, 3rem);
}

.about .section-inner {
  max-width: 1080px;
}

.section p {
  color: var(--muted);
  line-height: 1.8;
}

.about-columns {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2.5rem;
  align-items: center;
  margin-top: 0.5rem;
}

@media (min-width: 860px) {
  .about-columns {
    grid-template-columns: 1.15fr 0.85fr;
    gap: 4rem;
  }
}

.about-text {
  display: flex;
  flex-direction: column;
  gap: 1.35rem;
}

.about-lede {
  font-size: 1.15rem;
  line-height: 1.6;
  color: var(--about-accent);
  font-style: italic;
}

.about-text p:not(.about-lede) {
  font-size: 0.98rem;
  line-height: 1.75;
}

.resume-btn {
  align-self: flex-start;
  display: inline-flex;
  flex-direction: column;
  gap: 0.2rem;
  margin-top: 0.5rem;
  padding: 0.9rem 1.5rem;
  border: 1px solid var(--about-accent);
  border-radius: 10px;
  text-decoration: none;
  color: var(--text);
  cursor: pointer;
  transition: transform 0.2s ease, box-shadow 0.25s ease, background-color 0.25s ease;
}

.resume-btn-label {
  font-family: "Fira Code", "Courier New", Courier, monospace;
  font-size: 0.78rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--about-accent);
}

.resume-btn-action {
  font-weight: 600;
  font-size: 0.98rem;
}

.resume-btn:hover,
.resume-btn:focus-visible {
  transform: translateY(-2px);
  background: color-mix(in srgb, var(--about-accent) 10%, transparent);
  box-shadow: 0 14px 26px -18px color-mix(in srgb, var(--about-accent) 55%, transparent);
}

.resume-btn:focus-visible {
  outline: 2px solid var(--about-accent);
  outline-offset: 3px;
}

.about-photo {
  position: relative;
  max-width: 360px;
  margin-inline: auto;
}

.about-photo-accent {
  position: absolute;
  inset: 18px -18px -18px 18px;
  border: 2px solid var(--hero-accent);
  border-radius: 22px;
  z-index: 0;
}

.about-photo-frame {
  position: relative;
  z-index: 1;
  aspect-ratio: 4 / 5;
  border-radius: 22px;
  overflow: hidden;
  background: var(--surface);
  border: 1px solid var(--border);
  box-shadow: 0 24px 44px -30px rgba(0, 0, 0, 0.5);
}

.about-photo-frame img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.project-placeholder {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1rem;
  margin-top: 1.5rem;
}

.project-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 1.25rem;
  min-height: 120px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.project-card.empty {
  color: var(--muted);
  justify-content: center;
  align-items: center;
  text-align: center;
}

.project-status {
  color: var(--projects-accent);
  font-size: 0.85rem;
  font-weight: 600;
}

.tech-bgword {
  position: absolute;
  top: 50%;
  left: 0;
  transform: translateY(-50%);
  margin: 0;
  font-size: clamp(3.5rem, 16vw, 10rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  white-space: nowrap;
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--text) 14%, transparent) 0%,
    color-mix(in srgb, var(--text) 14%, transparent) 55%,
    var(--bg) 92%
  );
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  pointer-events: none;
  user-select: none;
  z-index: 0;
}

.tech-marquee-wrap {
  position: relative;
  z-index: 1;
  padding-block: 3.25rem;
  width: 100vw;
  margin-inline: calc(50% - 50vw);
  overflow: hidden;
  -webkit-mask-image: linear-gradient(90deg, transparent, black 8%, black 92%, transparent);
  mask-image: linear-gradient(90deg, transparent, black 8%, black 92%, transparent);
}

.tech-marquee-track {
  display: flex;
  gap: 1.25rem;
  width: max-content;
  animation: tech-scroll 42s linear infinite;
}

.tech-marquee-wrap:hover .tech-marquee-track {
  animation-play-state: paused;
}

.tech-pill {
  flex-shrink: 0;
  padding: 0.65rem 1.4rem;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--surface);
  box-shadow: 0 6px 16px -12px rgba(15, 23, 32, 0.3);
  font-family: "Fira Code", "Courier New", Courier, monospace;
  font-size: 0.9rem;
  color: var(--text);
  white-space: nowrap;
  transition: border-color 0.25s ease, color 0.25s ease, box-shadow 0.25s ease;
}

.tech-pill:hover {
  border-color: var(--hero-accent);
  color: var(--hero-accent);
  box-shadow: 0 10px 22px -14px color-mix(in srgb, var(--hero-accent) 55%, transparent);
}

@keyframes tech-scroll {
  from {
    transform: translateX(0);
  }

  to {
    transform: translateX(-25%);
  }
}

.contact-links {
  list-style: none;
  padding: 0;
  margin: 0 0 2rem;
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  max-width: 480px;
}

.contact-card {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 1rem 1.25rem;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
  text-decoration: none;
  color: inherit;
  cursor: pointer;
  transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
}

.contact-card:hover,
.contact-card:focus-visible {
  transform: translateX(6px);
  box-shadow: 0 10px 22px -14px rgba(15, 23, 32, 0.35);
}

.contact-card:focus-visible {
  outline: 2px solid var(--contact-accent);
  outline-offset: 2px;
}

.contact-icon {
  flex-shrink: 0;
  width: 42px;
  height: 42px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: "Fira Code", "Courier New", Courier, monospace;
  font-size: 0.75rem;
  font-weight: 700;
}

.contact-card--github .contact-icon {
  color: var(--text);
  background: rgba(127, 127, 127, 0.15);
}
.contact-card--github:hover {
  border-color: var(--text);
}

.contact-card--linkedin .contact-icon {
  color: var(--contact-accent);
  background: color-mix(in srgb, var(--contact-accent) 15%, transparent);
}
.contact-card--linkedin:hover {
  border-color: var(--contact-accent);
}

.contact-card--email .contact-icon {
  color: var(--projects-accent);
  background: color-mix(in srgb, var(--projects-accent) 15%, transparent);
}
.contact-card--email:hover {
  border-color: var(--projects-accent);
}

.contact-body {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  flex: 1;
}

.contact-platform {
  font-weight: 600;
  font-size: 0.95rem;
}

.contact-value {
  color: var(--muted);
  font-size: 0.85rem;
  font-family: "Fira Code", "Courier New", Courier, monospace;
}

.contact-arrow {
  flex-shrink: 0;
  font-size: 1.1rem;
  color: var(--muted);
  transition: transform 0.2s ease, color 0.2s ease;
}

.contact-card:hover .contact-arrow {
  transform: translateX(4px);
  color: var(--contact-accent);
}

.tech-title {
  margin: 0 0 1rem;
  color: var(--text);
  font-weight: 600;
}

.tech-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.9rem;
  list-style: none;
  padding: 0;
  margin: 0;
}

.tech-list li {
  color: var(--muted);
}

[data-theme="gray"] {
  --bg: #ECEDEF;
  --surface: #F7F8F9;
}

[data-theme="dark"] {
  color-scheme: dark;
  --bg: #1E1E1E;
  --surface: #282828;
  --text: #F2F1EF;
  --muted: #A3A29E;
  --border: rgba(255, 255, 255, 0.12);

  --hero-accent: #F0913D;
  --about-accent: #34D399;
  --contact-accent: #4CC2FA;
  --projects-accent: #FB7C97;
}

@media (max-width: 860px) {
  .page-content {
    gap: 4.5rem;
  }

  .tech-list,
  .project-placeholder {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 580px) {
  .page-content {
    padding: 2rem 0 3.5rem;
  }

  .about .section-inner,
  .contact .section-inner,
  .projects .section-inner {
    padding-left: 1rem;
  }

  .hero {
    min-height: 58vh;
  }

  .tech-bgword {
    font-size: clamp(2.6rem, 22vw, 4.5rem);
  }

  .tech-marquee-track {
    gap: 0.85rem;
  }

  .tech-pill {
    padding: 0.5rem 1rem;
    font-size: 0.8rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  .tech-marquee-track {
    animation: none;
  }

  .contact-card {
    transition: none;
  }
}
